INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.116.0',
  '2026-10-06',
  'Пульт ТВ: обои из альбома и настоящие ручки у фона',
  E'Фоном теперь можно взять не одну картинку, а целый альбом «Фото» или любую папку внутри него — кнопка «🖼 Все снимки» в окне выбора. Обои берутся случайно: новые при каждом открытии страницы, а если захотите — ещё и по таймеру, раз в 5, 15 или 60 минут. Смена плавная, через затухание.\n\nПоявился «Масштаб» и, главное, «Как вписывать». Раньше фон всегда растягивался до краёв экрана и обрезался — вертикальный снимок на широком телевизоре раздувался в четыре с лишним раза, и видно было меньше трети его высоты. Теперь есть «Целиком»: картинка показывается вся, без обрезки.\n\nУ размытия стало шесть шагов вместо четырёх, и рядом встала «Насыщенность» — от чёрно-белого до «Ярко». Размытая картинка выглядит мягче, если чуть убавить цвет, и наряднее, если прибавить.\n\nИз нового от себя: «Медленный наезд» — обои еле заметно плывут и приближаются, заодно это бережёт экран от выгорания. И выключатель «Постер сериала вместо фона»: раньше на экране сериала ваши обои всегда подменялись его размытым постером, теперь это можно оставить как есть.\n\nЗагруженная картинка хранится крупнее — до 2560×1440: на 4K-телевизоре прежняя копия растягивалась вдвое и выглядела мылом.',
  E'looks.json пополнился BgAlbum, BgEvery, BgFit, BgZoom, BgSat, BgPan и BgPoster. Последний — указателем: иначе «выключено» нельзя было бы отличить от «в старом файле настроек такого поля вовсе не было», и после обновления он молча включался бы обратно.\n\nАльбом: /api/settings отдаёт backgrounds — до 60 случайных снимков в экранном размере. Берутся готовые копии раздела «Фото» (тот же /photo/{id}?s=view): они кэшированы и ровно того размера, что нужен под обои. Перемешивает агент, а не страница: в альбоме бывает тысяча снимков, и список адресов не должен ехать в каждом ответе настроек целиком. Ролики пропускаются — кадр из них пришлось бы вынимать ffmpeg-ом на каждый новый.\n\nСтраница держит выбранные обои в bgPicked, крутит их по setInterval и при каждом loadLooks, не повторяя ту же картинку подряд. Смена идёт через гашение: если обои уже показаны и адрес другой, снимаем .on, ждём 420 мс и ставим новые.\n\nМасштаб живёт в CSS-переменной --bgz, потому что её же использует keyframes наезда; background-size ставится инлайном поверх шортката. На постере сериала эти ручки не применяются — обложку вписывать целиком незачем.\n\nЗамер в браузере: экранная копия вертикального снимка 607×1080 на блоке фона 2640×1379 при «Заполнить» идёт с увеличением 4,35× и видно 29 % высоты, при «Целиком» — 1,28× и вся картинка. Проверено также: выбор альбома и вложенной папки, отказ на пустой папке без сброса прежнего выбора, смена обоев между заходами, все переключатели доезжают до стилей (contain, --bgz 1.3, blur+saturate, класс наезда, таймер). Тесты в looks_test.go.'
);
-- +goose StatementEnd

